mapper.select:
SELECT ft.`tag_id`
FROM `note_folder_tag` ft
         JOIN `note_folder` f ON f.`id` = ft.`folder_id`
WHERE ft.`folder_id` = #{folderId}
  AND f.`user_id` = #{userId}

mapper.insert:
INSERT INTO `note_folder_tag` (`folder_id`, `tag_id`)
SELECT #{folderId}, `id` FROM `note_tag`
WHERE `id` = #{tagId} AND `user_id` = #{userId}
